/// A Control Change's assignment (the initial table, Owner's Manual pp.353-368).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CcAssign {
    /// 0 nothing, 1 FADER H, 2 FADER L, 3 ON, 4 PAN, 5 EQ ATT H, 6 EQ ATT L, 7 EQ ON.
    pub kind: u8,
    /// 0-95 INPUT, 96-103 BUS, 104-115 AUX, 116-119 MATRIX, 120 STEREO.
    pub target: u8,
}

const X: CcAssign = CcAssign { kind: 0, target: 0 };
macro_rules! a {
    ($k:expr, $t:expr) => {
        CcAssign { kind: $k, target: $t }
    };
}

